"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[3449],{84284(e,s,u){u.r(s),u.d(s,{assets:()=>l,contentTitle:()=>a,default:()=>d,frontMatter:()=>r,metadata:()=>n,toc:()=>o});const n=JSON.parse('{"id":"learning/courses/quantum-business-foundations/quantum-technology","title":"Technologie quantique","description":"Reconna\xeetre que la r\xe9solution de probl\xe8mes significatifs impliquera une combinaison de ressources quantiques et classiques.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/learning/courses/quantum-business-foundations/quantum-technology.mdx","sourceDirName":"learning/courses/quantum-business-foundations","slug":"/learning/courses/quantum-business-foundations/quantum-technology","permalink":"/learning/courses/quantum-business-foundations/quantum-technology","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-business-foundations/quantum-technology.mdx","tags":[],"version":"current","frontMatter":{"title":"Technologie quantique","description":"Reconna\xeetre que la r\xe9solution de probl\xe8mes significatifs impliquera une combinaison de ressources quantiques et classiques."},"sidebar":"tutorialsSidebar","previous":{"title":"Fondamentaux du calcul quantique","permalink":"/learning/courses/quantum-business-foundations/quantum-computing-fundamentals"},"next":{"title":"Impact sur les entreprises","permalink":"/learning/courses/quantum-business-foundations/business-impacts"}}');var t=u(74848),i=u(28453);const r={title:"Technologie quantique",description:"Reconna\xeetre que la r\xe9solution de probl\xe8mes significatifs impliquera une combinaison de ressources quantiques et classiques."},a="Technologie IBM Quantum {#ibm-quantum-technology}",l={},o=[{value:"Objectifs d&#39;apprentissage",id:"learning-objectives",level:2},{value:"IBM Quantum Platform",id:"ibm-quantum-platform",level:3},{value:"Qiskit Runtime",id:"qiskit-runtime",level:3},{value:"Ordinateurs quantiques supraconducteurs IBM",id:"ibm-superconducting-quantum-computers",level:3},{value:"Performances du calcul quantique",id:"quantum-computing-performance",level:2},{value:"Mesure des performances du calcul quantique",id:"measuring-quantum-computing-performance",level:3},{value:"V\xe9rifie ta compr\xe9hension",id:"check-your-understanding",level:3},{value:"Quelles sont les prochaines \xe9tapes du calcul quantique",id:"whats-next-in-quantum-computing",level:2},{value:"Utilit\xe9 quantique",id:"quantum-utility",level:3},{value:"Correction d&#39;erreurs",id:"error-correction",level:3},{value:"Feuille de route de d\xe9veloppement IBM Quantum",id:"ibm-quantum-development-roadmap",level:3},{value:"Le d\xe9fi 5k",id:"5k-challenge",level:3},{value:"Supercalculateurs centr\xe9s sur le quantique",id:"quantum-centric-supercomputers",level:3},{value:"Points cl\xe9s \xe0 retenir",id:"key-takeaways",level:2}];function c(e){const s={a:"a",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",img:"img",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components},{Details:n,IBMVideo:r}=s;return n||p("Details",!0),r||p("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n","\n",(0,t.jsx)(s.header,{children:(0,t.jsx)(s.h1,{id:"ibm-quantum-technology",children:"Technologie IBM Quantum"})}),"\n",(0,t.jsx)(s.p,{children:"La flotte d'ordinateurs quantiques IBM\xae, tous dot\xe9s d'au moins 127 qubits, est la plus grande au monde. Ces ordinateurs quantiques utilisent des qubits transmon supraconducteurs, qui ne sont pas le seul type de qubit, mais qui pr\xe9sentent de nombreux avantages. En combinant nos ordinateurs quantiques de classe mondiale avec Qiskit, nous permettons \xe0 nos utilisateurs d'explorer comment le calcul quantique peut \xeatre utile dans le monde d'aujourd'hui. Les partenaires industriels et les chercheurs utilisent la technologie IBM Quantum\xae pour explorer des calculs significatifs et des applications r\xe9alistes. Explorons l'\xe9tendue des programmes et des services qu'IBM Quantum offre \xe0 ses partenaires."}),"\n",(0,t.jsx)(s.p,{children:"Si tu fais partie d'une institution membre du r\xe9seau IBM Quantum, assure-toi de contacter le groupe de calcul quantique de ton institution pour d\xe9terminer \xe0 quels avantages tu as acc\xe8s."}),"\n",(0,t.jsx)(s.h2,{id:"learning-objectives",children:"Objectifs d'apprentissage"}),"\n",(0,t.jsx)(s.p,{children:"\xc0 la fin de ce module, tu devrais \xeatre en mesure de :"}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsx)(s.li,{children:"Reconna\xeetre que la r\xe9solution de probl\xe8mes significatifs impliquera une combinaison de ressources quantiques et classiques."}),"\n",(0,t.jsx)(s.li,{children:"Identifier le mat\xe9riel, les logiciels et les services disponibles pour r\xe9soudre des probl\xe8mes significatifs."}),"\n",(0,t.jsx)(s.li,{children:"D\xe9crire comment mesurer les performances du calcul quantique, notamment l'\xe9chelle, la qualit\xe9 et la vitesse."}),"\n"]}),"\n",(0,t.jsx)(s.h3,{id:"ibm-quantum-platform",children:"IBM Quantum Platform"}),"\n",(0,t.jsx)(s.p,{children:"IBM Quantum Platform fournit une suite d'outils de calcul quantique qui regroupe toutes les ressources de recherche et de d\xe9veloppement dont les utilisateurs ont besoin pour accomplir de grandes choses, en un seul endroit. Les utilisateurs peuvent cr\xe9er un compte et se connecter pour acc\xe9der aux ordinateurs quantiques IBM, voir les d\xe9tails des ordinateurs, suivre les charges de travail et acc\xe9der au mat\xe9riel p\xe9dagogique dans la Documentation et l'Apprentissage."}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsxs)(s.li,{children:["La ",(0,t.jsx)(s.a,{href:"https://quantum.cloud.ibm.com/",children:"page d'accueil"})," sert de point de d\xe9part principal pour l'\xe9cosyst\xe8me produit, o\xf9 les utilisateurs peuvent obtenir leurs cl\xe9s API, consulter un r\xe9sum\xe9 de leurs instances et informations d'utilisation, voir les d\xe9tails des emplois r\xe9cents et acc\xe9der \xe0 des liens utiles vers d'autres endroits de la plateforme."]}),"\n",(0,t.jsxs)(s.li,{children:["La ",(0,t.jsx)(s.a,{href:"/docs",children:"Documentation"})," regroupe la documentation Qiskit, la documentation du service et les informations de r\xe9f\xe9rence API en un seul endroit, organis\xe9 de mani\xe8re \xe0 soutenir les flux de travail naturels des utilisateurs."]}),"\n",(0,t.jsxs)(s.li,{children:["L'",(0,t.jsx)(s.a,{href:"/learning",children:"Apprentissage"})," est le foyer du mat\xe9riel \xe9ducatif, notamment les cours et les modules d'enseignement, ainsi que le Circuit Composer interactif (\xe0 venir). Ce combin\xe9 d'\xe9diteur graphique et de code permet aux utilisateurs de prototyper, simuler et d\xe9boguer des circuits visuellement, puis de les ex\xe9cuter sur les ordinateurs quantiques IBM."]}),"\n"]}),"\n",(0,t.jsx)(s.h3,{id:"qiskit-runtime",children:"Qiskit Runtime"}),"\n",(0,t.jsx)(s.p,{children:"Qiskit Runtime est une architecture portative, s\xe9curis\xe9e et conteneuris\xe9e qui ex\xe9cute des programmes quantiques sur une unit\xe9 informatique classique \xe9troitement int\xe9gr\xe9e au processeur quantique. Qiskit Runtime permet \xe0 l'ordinateur quantique de faire partie de tout environnement informatique pour acc\xe9l\xe9rer le calcul \u2014 similaire \xe0 une unit\xe9 de traitement graphique (GPU) \u2014 et g\xe8re l'orchestration des emplois et le transfert de donn\xe9es vers l'unit\xe9 de traitement quantique, maximisant l'efficacit\xe9."}),"\n",(0,t.jsx)(s.p,{children:"Qiskit et Qiskit Runtime facilitent l'orchestration rapide de programmes sur les ressources de calcul dans le cloud. IBM construit des intergiciels pour le quantique afin de maximiser les performances des applications quantiques s'ex\xe9cutant sur des ressources de calcul quantiques et classiques parall\xe9lis\xe9es et bas\xe9es sur le cloud. Ces intergiciels incluent la bo\xeete \xe0 outils de d\xe9coupe de circuits et notre architecture quantique serverless."}),"\n",(0,t.jsxs)(s.p,{children:["L'",(0,t.jsx)(s.a,{href:"https://docs.quantum.ibm.com/api/qiskit-addon-cutting",children:"addon Qiskit de d\xe9coupe de circuits"})," permet aux d\xe9veloppeurs de d\xe9couper de grands circuits en circuits plus petits adapt\xe9s aux ordinateurs quantiques actuels. La d\xe9coupe de circuits utilise le calcul classique pour prendre en charge une partie de la charge computationnelle d'un circuit quantique pour d\xe9passer ce qu'on peut r\xe9aliser avec l'un ou l'autre seul. Des outils suppl\xe9mentaires aident \xe0 reconstruire les circuits avec des ressources classiques et \xe0 assembler les r\xe9sultats finaux."]}),"\n",(0,t.jsxs)(s.p,{children:[(0,t.jsx)(s.a,{href:"/guides/serverless",children:"Quantum Serverless"})," est une bo\xeete \xe0 outils d'orchestration multi-cloud pour connecter des ressources classiques \xe9lastiques avec le service Qiskit Runtime d'IBM. Quantum Serverless permet aux d\xe9veloppeurs de se concentrer sur le code, plut\xf4t que sur l'approvisionnement des ressources."]}),"\n",(0,t.jsx)(s.h3,{id:"ibm-superconducting-quantum-computers",children:"Ordinateurs quantiques supraconducteurs IBM"}),"\n",(0,t.jsxs)(s.p,{children:["Les processeurs quantiques IBM utilisent un type physique de qubit appel\xe9 ",(0,t.jsx)(s.strong,{children:"qubit transmon supraconducteur"}),", fabriqu\xe9 \xe0 partir de mat\xe9riaux supraconducteurs model\xe9s sur un substrat de silicium. D'autres processeurs quantiques pourraient utiliser des qubits photoniques, fabriqu\xe9s \xe0 partir de photons individuels de lumi\xe8re, ou des qubits \xe0 ions pi\xe9g\xe9s, qui stockent des informations dans des particules atomiques charg\xe9es. Pour faciliter le flux du courant \xe9lectrique, les qubits supraconducteurs doivent \xeatre maintenus \xe0 des temp\xe9ratures extr\xeamement basses \u2014 proches du z\xe9ro absolu."]}),"\n",(0,t.jsx)(s.p,{children:(0,t.jsx)(s.img,{alt:"Processeur IBM \xe0 127 qubits",src:u(60794).A+"",width:"450",height:"450"})}),"\n",(0,t.jsx)(s.p,{children:(0,t.jsx)(s.em,{children:"Processeur IBM \xe0 127 qubits"})}),"\n",(0,t.jsx)(s.h2,{id:"quantum-computing-performance",children:"Performances du calcul quantique"}),"\n",(0,t.jsx)(s.h3,{id:"measuring-quantum-computing-performance",children:"Mesure des performances du calcul quantique"}),"\n",(0,t.jsx)(s.p,{children:"Un ordinateur quantique universel tol\xe9rant aux fautes est le grand d\xe9fi du calcul quantique. C'est un dispositif capable d'effectuer correctement des op\xe9rations quantiques universelles \xe0 l'aide de composants peu fiables. Les ordinateurs quantiques d'aujourd'hui ne sont pas tol\xe9rants aux fautes."}),"\n",(0,t.jsx)(s.p,{children:"Pour comparer les ordinateurs quantiques entre eux, le nombre de qubits n'est pas suffisant. De nombreux autres d\xe9tails doivent \xeatre pris en compte, comme les taux d'erreur et la fa\xe7on dont le syst\xe8me est c\xe2bl\xe9. Il existe quatre m\xe9triques cl\xe9s pour mesurer les performances du calcul quantique :"}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsxs)(s.li,{children:[(0,t.jsx)(s.strong,{children:"\xc9chelle"})," \u2014 Mesur\xe9e par le ",(0,t.jsx)(s.strong,{children:"nombre de qubits"}),", ce qui indique la quantit\xe9 d'informations qu'on peut encoder dans l'ordinateur quantique."]}),"\n",(0,t.jsxs)(s.li,{children:[(0,t.jsx)(s.strong,{children:"Qualit\xe9"})," \u2014 Mesur\xe9e par le ",(0,t.jsx)(s.strong,{children:"Volume Quantique"}),", ce qui indique la qualit\xe9 des circuits et la fid\xe9lit\xe9 avec laquelle les circuits sont impl\xe9ment\xe9s dans le mat\xe9riel."]}),"\n",(0,t.jsxs)(s.li,{children:[(0,t.jsx)(s.strong,{children:"Vitesse"})," \u2014 Mesur\xe9e par les ",(0,t.jsx)(s.strong,{children:"CLOPS (Circuit Layer Operations Per Second)"}),", ce qui indique combien de circuits peuvent \xeatre ex\xe9cut\xe9s sur le mat\xe9riel dans un temps donn\xe9."]}),"\n",(0,t.jsxs)(s.li,{children:[(0,t.jsx)(s.strong,{children:"Fid\xe9lit\xe9 des couches"})," \u2014 Mesur\xe9e par l'",(0,t.jsx)(s.strong,{children:"EPLG (Errors Per Layered Gate)"}),", ce qui d\xe9crit comment les erreurs se produisent lorsque des op\xe9rations sont effectu\xe9es sur des qubits."]}),"\n"]}),"\n",(0,t.jsxs)(s.p,{children:["Pour une description plus d\xe9taill\xe9e de certaines des m\xe9triques ci-dessus, consulte ",(0,t.jsx)(s.a,{href:"https://research.ibm.com/blog/quantum-metric-layer-fidelity",children:"cet article"})," sur le blog IBM Research. Chaque phase dans l'adoption du calcul quantique dans l'industrie est port\xe9e par l'augmentation du Volume Quantique, qui est calcul\xe9 \xe0 l'aide de divers param\xe8tres tels que la largeur du circuit, la connectivit\xe9 des qubits et les taux d'erreur."]}),"\n",(0,t.jsx)(s.p,{children:"La d\xe9finition technique du Volume Quantique est difficile \xe0 communiquer sans \xe9quations.\nDario Gil, Directeur de la Recherche chez IBM, explique :"}),"\n",(0,t.jsx)(r,{id:"133345140",title:"Dario Gil explains the concept of quantum volume. In particular he explains how and why it depends on both qubit count and error rates."}),"\n",(0,t.jsx)(s.p,{children:"Pour mieux comprendre le Volume Quantique, consid\xe8re l'analogie int\xe9ressante suivante. La section ci-dessous couvre le temps, l'espace et les taux d'erreur en termes de visite touristique de New York City."}),"\n",(0,t.jsx)(s.p,{children:(0,t.jsx)(s.strong,{children:"Visiter les \xe9tats du Volume Quantique"})}),"\n",(0,t.jsxs)(s.p,{children:["Le Volume Quantique d\xe9crit le plus grand espace de calcul quantique qu'un ordinateur quantique peut explorer, o\xf9 le volume de l'espace quantique est 2",(0,t.jsx)("sup",{children:"N"}),", avec N \xe9tant le nombre de qubits, c'est-\xe0-dire la dimension usuelle de l'espace des \xe9tats. Nous utilisons intentionnellement le mot \xab espace \xbb ici car une fois qu'on mentionne l'espace, il est facile de penser \xe0 un volume."]}),"\n",(0,t.jsx)(s.p,{children:"Le facteur limitant cette exploration est le taux d'erreur. Le taux d'erreur peut \xeatre assimil\xe9 \xe0 la quantit\xe9 de temps qu'on est autoris\xe9 \xe0 explorer l'espace. Plus il y a d'erreurs, moins on a de temps pour explorer. Plus l'espace de calcul est grand, plus il faut de temps pour l'explorer enti\xe8rement, et donc on a besoin d'un ordinateur quantique avec un taux d'erreur plus faible."}),"\n",(0,t.jsx)(s.p,{children:"Imagine un touriste qui explore New York City. Le touriste veut explorer toute la ville, ce qui signifie qu'il veut un volume touristique de la taille de NYC. Si on lui donne seulement un jour, il n'y a aucun moyen d'explorer autant d'espace, donc le touriste n'obtient pas le volume touristique souhait\xe9. Cependant, si on lui donne trois jours, le touriste pourrait probablement visiter tous les meilleurs endroits et obtenir le volume touristique n\xe9cessaire de NYC."}),"\n",(0,t.jsx)(s.p,{children:"Maintenant, que se passe-t-il si on donne plus de temps au touriste mais qu'on restreint quand m\xeame l'espace \xe0 NYC ? En d'autres termes, que se passe-t-il si on garde le nombre de qubits constant mais qu'on diminue le taux d'erreur ? Il n'y a alors aucun avantage pour le touriste puisqu'il a d\xe9j\xe0 explor\xe9 la ville et ne fait que repasser aux m\xeames endroits. Le volume touristique reste le m\xeame. Au lieu de cela, avec plus de temps, il est plus intelligent pour le touriste d'augmenter le nombre de sites touristiques \xe0 visiter."}),"\n",(0,t.jsx)(s.p,{children:"Ou supposons qu'on garde le temps fixe \xe0 trois jours mais que le touriste d\xe9cide d'essayer d'explorer toute NYC et Long Island ? En d'autres termes, que se passe-t-il si on fixe le taux d'erreur mais qu'on ajoute plus de qubits ? Encore une fois, le volume touristique reste celui de NYC car le touriste ne peut pas explorer le plus grand espace dans le temps imparti. Ainsi, \xeatre un meilleur touriste, et atteindre un plus grand volume touristique, n\xe9cessite d'augmenter simultan\xe9ment l'espace de visite et la quantit\xe9 de temps que le touriste est autoris\xe9 \xe0 explorer."}),"\n",(0,t.jsx)(s.p,{children:"De la m\xeame fa\xe7on, construire de meilleurs ordinateurs quantiques atteignant des Volumes Quantiques plus \xe9lev\xe9s n\xe9cessite d'augmenter simultan\xe9ment l'espace de calcul quantique (nombre de qubits) tout en diminuant le taux d'erreur (augmentant la dur\xe9e pendant laquelle l'algorithme peut s'ex\xe9cuter). Par exemple, gr\xe2ce aux avanc\xe9es dans les architectures de couplage ajustable, IBM a doubl\xe9 le volume quantique deux fois en seulement un an !"}),"\n",(0,t.jsx)(s.p,{children:(0,t.jsx)(s.img,{alt:"Volume Quantique",src:u(45223).A+"",width:"720",height:"405"})}),"\n",(0,t.jsx)(s.p,{children:"Cependant, \xe0 mesure que le calcul quantique \xe9volue, on commence \xe0 se soucier davantage du travail utile que nos ordinateurs quantiques peuvent accomplir dans un d\xe9lai raisonnable. Si on mesure l'\xe9chelle par le nombre de qubits et la qualit\xe9 par le volume quantique, alors la vitesse de traitement quantique est la mesure du travail utile que ces qubits peuvent accomplir dans un d\xe9lai raisonnable. On la d\xe9finit comme le nombre de circuits primitifs pouvant \xeatre trait\xe9s par seconde. C'est similaire aux FLOPS en informatique classique \u2014 le nombre d'op\xe9rations en virgule flottante par seconde. Am\xe9liorer la vitesse QPU est la cl\xe9 du calcul quantique pratique. Comme la programmation d'ordinateurs classiques, la programmation quantique n\xe9cessite l'ex\xe9cution de nombreux circuits. Une vitesse QPU raisonnable permettra aux utilisateurs d'int\xe9grer le calcul quantique dans leurs flux de travail."}),"\n",(0,t.jsx)(s.h3,{id:"check-your-understanding",children:"V\xe9rifie ta compr\xe9hension"}),"\n",(0,t.jsx)(s.p,{children:"Lis la question ci-dessous, r\xe9fl\xe9chis \xe0 ta r\xe9ponse, puis clique sur le triangle pour r\xe9v\xe9ler la solution."}),"\n",(0,t.jsxs)(n,{children:[(0,t.jsx)("summary",{children:(0,t.jsx)(s.p,{children:"Vrai ou faux : Le Volume Quantique d\xe9signe la taille des r\xe9frig\xe9rateurs cryog\xe9niques qui abritent les ordinateurs quantiques IBM."})}),(0,t.jsx)(s.p,{children:"Faux. Le Volume Quantique est un nombre unique destin\xe9 \xe0 r\xe9sumer les performances des ordinateurs quantiques d'aujourd'hui."})]}),"\n",(0,t.jsx)(s.h2,{id:"whats-next-in-quantum-computing",children:"Quelles sont les prochaines \xe9tapes du calcul quantique"}),"\n",(0,t.jsx)(s.p,{children:"Les ordinateurs quantiques d'aujourd'hui, et ceux attendus dans un avenir pr\xe9visible, sont bruit\xe9s. Cela signifie qu'ils sont sensibles aux perturbations environnementales qui peuvent affecter la fid\xe9lit\xe9 des r\xe9sultats. De la m\xeame fa\xe7on que l'informatique classique a \xe9volu\xe9 gr\xe2ce \xe0 la mise \xe0 l'\xe9chelle modulaire des processeurs, \xe0 l'efficacit\xe9 computationnelle et \xe0 la parall\xe9lisation, nous voyons le calcul quantique \xe9voluer pour r\xe9aliser son plein potentiel. Alors que nous travaillons vers des ordinateurs quantiques enti\xe8rement tol\xe9rants aux fautes, nous voulons r\xe9soudre des probl\xe8mes utiles avec le mat\xe9riel et les logiciels que nous poss\xe9dons aujourd'hui."}),"\n",(0,t.jsx)(s.h3,{id:"quantum-utility",children:"Utilit\xe9 quantique"}),"\n",(0,t.jsx)(s.p,{children:"IBM Quantum et l'Universit\xe9 de Californie, Berkeley ont pr\xe9sent\xe9 des preuves que les ordinateurs quantiques peuvent apporter de la valeur plus t\xf4t que pr\xe9vu gr\xe2ce aux avanc\xe9es dans le mat\xe9riel IBM Quantum et les m\xe9thodes d'att\xe9nuation des erreurs. Au-del\xe0 d'une simple preuve de concept, nous avons livr\xe9 des r\xe9sultats suffisamment pr\xe9cis pour \xeatre utiles. Le mod\xe8le de calcul que nous avons explor\xe9 avec ce travail est un aspect central de nombreux algorithmes con\xe7us pour les ordinateurs quantiques \xe0 court terme."}),"\n",(0,t.jsx)(s.p,{children:"La boucle de r\xe9troaction entre le quantique et le classique est essentielle pour faire avancer les technologies quantiques. En se concentrant sur l'utilit\xe9 quantique, on utilise le quantique pour sonder des probl\xe8mes complexes qui d\xe9fient les frameworks de calcul haute performance existants, puis on v\xe9rifie les r\xe9sultats classiquement. Ce va-et-vient continu entre l'ex\xe9cution d'un circuit complexe par le quantique et la v\xe9rification des r\xe9sultats quantiques par les ordinateurs classiques am\xe9liorera les deux domaines computationnels et donnera aux utilisateurs confiance dans les capacit\xe9s des ordinateurs quantiques \xe0 court terme."}),"\n",(0,t.jsx)(r,{id:"134056420",title:"This video outlines how noisy quantum computers use error mitigation to out-perform brute force classical methods on an example problem."}),"\n",(0,t.jsxs)(n,{children:[(0,t.jsx)("summary",{children:(0,t.jsx)(s.p,{children:"Lecture facultative \u2014 cliquez sur le triangle pour en savoir plus sur l'exp\xe9rience"})}),(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsx)(s.p,{children:"Dans cette exp\xe9rience, nous avons utilis\xe9 les 127 qubits de notre processeur IBM Quantum Eagle pour simuler le comportement changeant d'un syst\xe8me qui se mappe naturellement \xe0 un ordinateur quantique, appel\xe9 le mod\xe8le d'Ising quantique. Les mod\xe8les d'Ising sont des simplifications de la nature qui repr\xe9sentent des atomes en interaction comme un r\xe9seau de syst\xe8mes quantiques \xe0 deux choix en interaction dans un champ d'\xe9nergie. Ces syst\xe8mes ressemblent beaucoup aux qubits \xe0 deux \xe9tats qui composent nos ordinateurs quantiques, ce qui en fait un bon candidat pour tester les capacit\xe9s de nos m\xe9thodes. Nous avons utilis\xe9 ZNE pour essayer de calculer avec pr\xe9cision une propri\xe9t\xe9 du syst\xe8me appel\xe9e sa valeur d'esp\xe9rance \u2014 essentiellement une moyenne pond\xe9r\xe9e des r\xe9sultats possibles du circuit."}),"\n"]}),"\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsx)(s.p,{children:"Simultan\xe9ment, l'\xe9quipe de Berkeley a tent\xe9 de simuler le m\xeame syst\xe8me en utilisant des m\xe9thodes de r\xe9seau tensoriel avec l'aide de supercalculateurs avanc\xe9s situ\xe9s au National Energy Research Scientific Computing Center (NERSC) du Lawrence Berkeley National Lab et \xe0 l'Universit\xe9 Purdue."}),"\n"]}),"\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsx)(s.p,{children:"Les m\xe9thodes quantiques ont continu\xe9 \xe0 s'accorder avec les m\xe9thodes exactes. Mais finalement, les m\xe9thodes d'approximation classiques ont commenc\xe9 \xe0 faillir \xe0 mesure que la difficult\xe9 augmentait."}),"\n"]}),"\n",(0,t.jsxs)(s.li,{children:["\n",(0,t.jsx)(s.p,{children:"Finalement, nous avons demand\xe9 aux deux ordinateurs d'effectuer des calculs au-del\xe0 de ce qui pouvait \xeatre calcul\xe9 exactement \u2014 et l'ordinateur quantique a retourn\xe9 une r\xe9ponse en laquelle nous avions plus confiance pour \xeatre correcte. Et m\xeame si nous ne pouvons pas prouver si cette r\xe9ponse \xe9tait r\xe9ellement correcte, le succ\xe8s d'Eagle sur les ex\xe9cutions pr\xe9c\xe9dentes de l'exp\xe9rience nous a donn\xe9 confiance qu'elles l'\xe9taient."}),"\n"]}),"\n"]})]}),"\n",(0,t.jsx)(s.h3,{id:"error-correction",children:"Correction d'erreurs"}),"\n",(0,t.jsx)(s.p,{children:"La correction d'erreurs est un domaine de recherche cl\xe9 depuis des d\xe9cennies. Mais pendant la majeure partie de ce temps, les techniques th\xe9oriques de correction d'erreurs ont \xe9t\xe9 impraticables \xe0 impl\xe9menter sur de vrais ordinateurs quantiques, principalement en raison du tr\xe8s grand nombre de qubits n\xe9cessaires. En effet, de nombreux experts pr\xe9disent que le calcul quantique tol\xe9rant aux fautes pratique (FTQC) n\xe9cessitera des millions de qubits physiques. Mais dans un r\xe9cent article publi\xe9 en couverture de Nature, des chercheurs d'IBM ont introduit un nouveau code, que nous appelons le code Gross, qui surmonte cette limitation."}),"\n",(0,t.jsxs)(s.p,{children:["L'article ",(0,t.jsx)(s.a,{href:"https://www.nature.com/articles/s41586-024-07107-7",children:"High-threshold and low-overhead fault-tolerant quantum memory"})," d\xe9crit le nouveau code de correction d'erreurs quantiques qui est environ 10 fois plus efficace que les m\xe9thodes pr\xe9c\xe9dentes pour prot\xe9ger les donn\xe9es quantiques d\xe9licates de l'accumulation d'erreurs. Pour appr\xe9cier \xe0 quel point on est maintenant plus proche du d\xe9but de la correction d'erreurs, consid\xe8re qu'en utilisant le code Gross, tu peux prot\xe9ger 12 qubits logiques pendant environ un million de cycles de v\xe9rifications d'erreurs en utilisant 288 qubits."]}),"\n",(0,t.jsx)(s.p,{children:"On ne s'attend pas \xe0 ce que la correction d'erreurs remplace soudainement l'att\xe9nuation et la suppression d'erreurs. Au contraire, au cours des prochaines ann\xe9es, l'att\xe9nuation et la suppression d'erreurs continueront \xe0 jouer un r\xf4le central, aux c\xf4t\xe9s d'un nombre croissant de qubits corrig\xe9s en erreurs."}),"\n",(0,t.jsx)(s.h3,{id:"ibm-quantum-development-roadmap",children:"Feuille de route de d\xe9veloppement IBM Quantum"}),"\n",(0,t.jsx)(s.p,{children:"Nous sommes maintenant fermement dans l'\xe8re de l'utilit\xe9 quantique. Cela signifie que les ordinateurs quantiques sont meilleurs en calcul quantique que les ordinateurs classiques, et peuvent \xeatre mis \xe0 profit par nos utilisateurs pour d\xe9couvrir de nouveaux algorithmes et rechercher des avantages quantiques. Notre feuille de route d\xe9crit nos jalons historiques et nos plans pour atteindre un avantage quantique \xe0 court terme d'ici 2026."}),"\n",(0,t.jsxs)(s.p,{children:["D'ici 2029, nous livrerons Starling \u2014 un grand ordinateur quantique tol\xe9rant aux fautes capable d'ex\xe9cuter des circuits quantiques comprenant 100 millions de portes quantiques sur 200 qubits logiques. Nous construisons ce syst\xe8me en ce moment m\xeame dans notre installation historique \xe0 Poughkeepsie, New York. Apprends-en plus sur notre progression dans le ",(0,t.jsx)(s.a,{href:"http://www.ibm.com/downloads/documents/us-en/131cf87ab63319bf",children:"PDF de la feuille de route guid\xe9e."})]}),"\n",(0,t.jsx)(s.p,{children:(0,t.jsx)(s.img,{alt:"Feuille de route de d\xe9veloppement",src:u(80305).A+"",width:"1920",height:"1080"})}),"\n",(0,t.jsxs)(s.p,{children:["En savoir plus sur la feuille de route de d\xe9veloppement IBM Quantum ",(0,t.jsx)(s.a,{href:"https://www.ibm.com/quantum/roadmap",children:"ici"}),"."]}),"\n",(0,t.jsx)(s.h3,{id:"5k-challenge",children:"Le d\xe9fi 5k"}),"\n",(0,t.jsx)(s.p,{children:"IBM travaille avec la communaut\xe9 de recherche quantique pour trouver des cas d'usage potentiels qui pourraient b\xe9n\xe9ficier du calcul quantique. Nous fournissons des outils de plus en plus puissants pour que les utilisateurs puissent explorer des probl\xe8mes urgents avec le quantique. En 2024, nous avons sorti un outil capable de calculer des observables non biais\xe9es de circuits longs et de haute qualit\xe9. Trouver ce qui peut \xeatre fait avec cette combinaison de 100+ qubits et de circuits profonds s'appelait autrefois le \xab d\xe9fi 100x100 \xbb. Mais le nombre pr\xe9cis de qubits et la profondeur de chacun importent moins que l'exploitation de la puissance de la combinaison. Imagine ce qui est possible avec 5 000 circuits quantiques dans un seul calcul. Les utilisateurs peuvent ex\xe9cuter des circuits quantiques avec une complexit\xe9 et un temps d'ex\xe9cution au-del\xe0 des capacit\xe9s des meilleurs ordinateurs classiques d'aujourd'hui. Nous sommes impatients de voir ce que la communaut\xe9 quantique construira pour nous aider \xe0 exploiter la puissance du quantique et \xe0 r\xe9soudre des probl\xe8mes importants."}),"\n",(0,t.jsx)(s.h3,{id:"quantum-centric-supercomputers",children:"Supercalculateurs centr\xe9s sur le quantique"}),"\n",(0,t.jsx)(s.p,{children:"Aller au-del\xe0 des processeurs \xe0 puce unique est la cl\xe9 pour r\xe9soudre des probl\xe8mes \xe0 grande \xe9chelle. En 2024, nous avons pr\xe9sent\xe9 Crossbill, le premier processeur unique fabriqu\xe9 \xe0 partir de plusieurs puces. Ce sont les premi\xe8res \xe9tapes pour inaugurer une nouvelle \xe8re de mise \xe0 l'\xe9chelle, offrant un chemin clair vers 100 000 qubits et au-del\xe0 avec la supercalculation centr\xe9e sur le quantique. C'est une architecture informatique modulaire qui permet la mise \xe0 l'\xe9chelle. Elle combine la communication et le calcul quantiques pour augmenter la capacit\xe9 computationnelle, tout en employant des intergiciels cloud hybrides pour int\xe9grer de mani\xe8re transparente les flux de travail quantiques et classiques."}),"\n",(0,t.jsx)(s.p,{children:"La r\xe9solution des probl\xe8mes les plus complexes du monde n\xe9cessitera une combinaison de ressources classiques et quantiques. De plus, cela d\xe9pendra de la collaboration continue entre l'industrie et le monde acad\xe9mique."}),"\n",(0,t.jsx)(s.h2,{id:"key-takeaways",children:"Points cl\xe9s \xe0 retenir"}),"\n",(0,t.jsx)(s.p,{children:"Tu peux garder ces points cl\xe9s \xe0 l'esprit :"}),"\n",(0,t.jsxs)(s.ul,{children:["\n",(0,t.jsx)(s.li,{children:"Les ordinateurs quantiques d'aujourd'hui ne sont pas tol\xe9rants aux fautes."}),"\n",(0,t.jsx)(s.li,{children:"Le Volume Quantique est une mesure holistique de la qualit\xe9 d'un ordinateur quantique. Plus le Volume Quantique est \xe9lev\xe9, mieux c'est. Parler uniquement du nombre de qubits est trompeur."}),"\n",(0,t.jsx)(s.li,{children:"Pour mesurer les performances des ordinateurs quantiques, il existe quatre m\xe9triques cl\xe9s : l'\xe9chelle, la qualit\xe9, la vitesse et la fid\xe9lit\xe9 des couches."}),"\n",(0,t.jsx)(s.li,{children:"Une exp\xe9rience conjointe IBM Quantum-UC Berkeley a pr\xe9sent\xe9 des preuves que les ordinateurs quantiques IBM fournissent des r\xe9sultats fiables et pr\xe9cis pour des probl\xe8mes de simulation difficiles \xe0 l'\xe9chelle de 127 qubits."}),"\n",(0,t.jsx)(s.li,{children:"La supercalculation centr\xe9e sur le quantique signifie traiter le quantique comme une pi\xe8ce d'un paradigme HPC plus large avec le classique et le quantique fonctionnant comme une seule unit\xe9 computationnelle."}),"\n"]})]})}function d(e={}){const{wrapper:s}={...(0,i.R)(),...e.components};return s?(0,t.jsx)(s,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}function p(e,s){throw new Error("Expected "+(s?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}},60794(e,s,u){u.d(s,{A:()=>n});const n=u.p+"assets/images/127qubit-processer-5f4e07dd161a5396ac24b1af43f9999a.avif"},80305(e,s,u){u.d(s,{A:()=>n});const n=u.p+"assets/images/IBM-Quantum-Development-and-Innovation-Roadmap-2025-f5804f9bec56cfc9744c8755f6d3a0a5.svg"},45223(e,s,u){u.d(s,{A:()=>n});const n=u.p+"assets/images/QV-ae503518346a4890c4c69e31ee36ea27.avif"},28453(e,s,u){u.d(s,{R:()=>r,x:()=>a});var n=u(96540);const t={},i=n.createContext(t);function r(e){const s=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function a(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:r(e.components),n.createElement(i.Provider,{value:s},e.children)}}}]);